def tau(k):
    if k == 1:
        return 1
    count = 0
    d = 1
    while d * d <= k:
        if k % d == 0:
            if d * d == k:
                count += 1
            else:
                count += 2
        d += 1
    return count

# Function to calculate the number of divisors (tau function)
def tau_prime(k):
    if k <= 0:
        return 0
    factors = {}
    d = 2
    temp = k
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

